38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
40	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
41	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
