50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
70	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
71	     */
72	    private static final Pattern EMAIL_PATTERN =
73	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        rejectMissingOrBlankFields(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
125	        owner.setEmail(normalizeEmail(owner.getEmail()));
126	        if (owner.getRegistrationDate() == null) {
127	            owner.setRegistrationDate(LocalDate.now());
128	        }
129	        rejectDuplicateTelephone(owner.getTelephone());
130	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
131	            assignHousehold(owner);
132	        } else {
133	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
134	        }
135	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
136	        this.clinicService.saveOwner(owner);
137	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
138	        headers.setLocation(UriComponentsBuilder.newInstance()
139	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
140	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
146	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
147	        if (currentOwner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        currentOwner.setAddress(ownerFieldsDto.getAddress());
151	        currentOwner.setCity(ownerFieldsDto.getCity());
152	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
153	        currentOwner.setLastName(ownerFieldsDto.getLastName());
154	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
155	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
156	        this.clinicService.saveOwner(currentOwner);
157	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Transactional
162	    @Override
163	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
164	        Owner owner = this.clinicService.findOwnerById(ownerId);
165	        if (owner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        this.clinicService.deleteOwner(owner);
169	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
175	        Owner owner = this.clinicService.findOwnerById(ownerId);
176	        if (owner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        HttpHeaders headers = new HttpHeaders();
180	        Pet pet = petMapper.toPet(petFieldsDto);
181	        owner.setId(ownerId);
182	        pet.setOwner(owner);
183	        pet.getType().setName(null);
184	        this.clinicService.savePet(pet);
185	        PetDto petDto = petMapper.toPetDto(pet);
186	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
187	            .buildAndExpand(pet.getId()).toUri());
188	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
194	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
195	        if (currentOwner != null) {
196	            Pet currentPet = this.clinicService.findPetById(petId);
197	            if (currentPet != null) {
198	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
199	                currentPet.setName(petFieldsDto.getName());
200	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
201	                this.clinicService.savePet(currentPet);
202	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
203	            }
204	        }
205	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
211	        HttpHeaders headers = new HttpHeaders();
212	        Visit visit = visitMapper.toVisit(visitFieldsDto);
213	        Pet pet = new Pet();
214	        pet.setId(petId);
215	        visit.setPet(pet);
216	        this.clinicService.saveVisit(visit);
217	        VisitDto visitDto = visitMapper.toVisitDto(visit);
218	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
219	            .buildAndExpand(visit.getId()).toUri());
220	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
221	    }
222	
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
227	        Owner owner = this.clinicService.findOwnerById(ownerId);
228	        if (owner != null) {
229	            Pet pet = owner.getPet(petId);
230	            if (pet != null) {
231	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
232	            }
233	        }
234	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	    }
236	
237	    /**
238	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
239	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
240	     *
241	     * @param fields the submitted owner fields
242	     * @throws RequiredFieldsMissingException if any of firstName, lastName, address, city or telephone is
243	     *                                        {@code null} or blank
244	     */
245	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
246	        List<String> missing = new ArrayList<>();
247	        if (isBlank(fields.getFirstName())) {
248	            missing.add("firstName");
249	        }
250	        if (isBlank(fields.getLastName())) {
251	            missing.add("lastName");
252	        }
253	        if (isBlank(fields.getAddress())) {
254	            missing.add("address");
255	        }
256	        if (isBlank(fields.getCity())) {
257	            missing.add("city");
258	        }
259	        if (isBlank(fields.getTelephone())) {
260	            missing.add("telephone");
261	        }
262	        if (!missing.isEmpty()) {
263	            throw new RequiredFieldsMissingException(missing);
264	        }
265	    }
266	
267	    private boolean isBlank(String value) {
268	        return value == null || value.isBlank();
269	    }
270	
271	    /**
272	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
273	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
274	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
275	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
276	     *
277	     * @param telephone the raw telephone value from the request
278	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
279	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
280	     */
281	    private String normalizeTelephone(String telephone) {
282	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
283	        String digits;
284	        if (cleaned.startsWith("+")) {
285	            digits = cleaned.substring(1);
286	        } else {
287	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
288	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
289	            digits = "61" + national;
290	        }
291	        if (!digits.matches("[0-9]{8,15}")) {
292	            throw new InvalidTelephoneException(cleaned);
293	        }
294	        return "+" + digits;
295	    }
296	
297	    /**
298	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
299	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
300	     * lower-cased.
301	     *
302	     * @param email the raw email value from the request, or {@code null} if omitted
303	     * @return the lower-cased email, or {@code null} if none was supplied
304	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
305	     */
306	    private String normalizeEmail(String email) {
307	        if (email == null) {
308	            return null;
309	        }
310	        String trimmed = email.strip();
311	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
312	            throw new InvalidEmailException(email);
313	        }
314	        return trimmed.toLowerCase(Locale.ROOT);
315	    }
316	
317	    /**
318	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
319	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
320	     *
321	     * @param telephone the normalized (E.164) telephone of the owner being created
322	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
323	     */
324	    /**
325	     * Builds the customer code assigned to a newly created owner, formatted {@code '<LAST3>-<NNNN>'} where
326	     * {@code LAST3} is the upper-cased first three letters of the owner's last name and {@code NNNN} is a
327	     * global 4-digit zero-padded sequence equal to one more than the current number of owners (e.g.
328	     * {@code 'SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes it.
329	     *
330	     * @param lastName the owner's last name
331	     * @return the assigned customer code
332	     */
333	    private String generateCustomerCode(String lastName) {
334	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
335	        int sequence = this.clinicService.findAllOwners().size() + 1;
336	        return String.format("%s-%04d", last3, sequence);
337	    }
338	
339	    private void rejectDuplicateTelephone(String telephone) {
340	        boolean taken = this.clinicService.findAllOwners().stream()
341	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
342	        if (taken) {
343	            throw new DuplicateTelephoneException(telephone);
344	        }
345	    }
346	
347	    /**
348	     * Rejects a create request whose owner shares both last name and address with an existing owner.
349	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
350	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
351	     * differing case) still count as the same household.
352	     *
353	     * @param lastName the last name of the owner being created
354	     * @param address the address of the owner being created
355	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
356	     */
357	    private void rejectDuplicateHousehold(String lastName, String address) {
358	        String normalizedLastName = normalizeForComparison(lastName);
359	        String normalizedAddress = normalizeForComparison(address);
360	        boolean taken = this.clinicService.findAllOwners().stream()
361	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
362	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
363	        if (taken) {
364	            throw new DuplicateHouseholdException(lastName, address);
365	        }
366	    }
367	
368	    /**
369	     * Assigns the owner being created into a shared household. When at least one existing owner has the
370	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
371	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
372	     * reused when present; otherwise a deterministic id derived from the household's last name and address
373	     * is minted, so independently created members of the same household converge on one value. When no
374	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
375	     *
376	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
377	     */
378	    private void assignHousehold(Owner owner) {
379	        String normalizedLastName = normalizeForComparison(owner.getLastName());
380	        String normalizedAddress = normalizeForComparison(owner.getAddress());
381	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
382	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
383	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
384	            .toList();
385	        if (housemates.isEmpty()) {
386	            return;
387	        }
388	        String householdId = housemates.stream()
389	            .map(Owner::getHouseholdId)
390	            .filter(id -> id != null && !id.isBlank())
391	            .findFirst()
392	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
393	        owner.setHouseholdId(householdId);
394	        for (Owner housemate : housemates) {
395	            if (!householdId.equals(housemate.getHouseholdId())) {
