406	     *
407	     * @param normalizedLastName the household's last name, already normalized for comparison
408	     * @param normalizedAddress the household's address, already normalized for comparison
409	     * @return a stable, shareable household identifier
410	     */
411	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
412	        String key = normalizedLastName + "|" + normalizedAddress;
413	        try {
414	            byte[] digest = MessageDigest.getInstance("SHA-256")
415	                .digest(key.getBytes(StandardCharsets.UTF_8));
416	            StringBuilder sb = new StringBuilder(digest.length * 2);
417	            for (byte b : digest) {
418	                sb.append(String.format("%02x", b));
419	            }
