428	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
429	     * lower-cased.
430	     *
431	     * @param value the raw value to normalize (may be {@code null})
432	     * @return the normalized value, or an empty string when {@code value} is {@code null}
433	     */
434	    private String normalizeForComparison(String value) {
435	        if (value == null) {
436	            return "";
437	        }
